    public function testFilteringDoesNotModifyOriginalObject(): void
    {
        $original = new Entity([
            Entity::DATA => [300, 350, 400, 5000],
        ]);

        $calculator = new Calculator($original);

        $this->assertSame(
            [300, 350, 400, 5000],
            $original->data()
        );

        $this->assertSame(
            [300, 350, 400],
            $calculator->filteredObject()
